func newProfile() unsafe.Pointer { return unsafe.Pointer(new(agentprofile.Profile)) }

func newNProfile(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]agentprofile.Profile, n)))
}

func ptrProfile(p unsafe.Pointer, c int32) any {
	r := (*agentprofile.Profile)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.Subject))
	case 4:
		return (**string)(unsafe.Pointer(&r.UserID))
	case 5:
		return (*string)(unsafe.Pointer(&r.Status))
	case 6:
		return (*string)(unsafe.Pointer(&r.Trigger))
	case 7:
		return (**string)(unsafe.Pointer(&r.RequestedByID))
	case 8:
		return &r.Content
	case 9:
		return &r.Facts
	case 10:
		return &r.GuidanceIDs
	case 11:
		return &r.Digest
	case 12:
		return &r.Model
	case 13:
		return (*string)(unsafe.Pointer(&r.ProviderID))
	case 14:
		return (*int64)(unsafe.Pointer(&r.InputTokens))
	case 15:
		return (*int64)(unsafe.Pointer(&r.OutputTokens))
	case 16:
		return &r.ErrorMessage
	case 17:
		return &r.CheckedAt
	case 18:
		return &r.Version
	case 19:
		return &r.CreatedAt
	case 20:
		return &r.UpdatedAt
	}
	return nil
}

func valueProfile(p unsafe.Pointer, c int32) any {
	r := (*agentprofile.Profile)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.Subject)
	case 4:
		if r.UserID == nil {
			return nil
		}
		return string(*r.UserID)
	case 5:
		return string(r.Status)
	case 6:
		return string(r.Trigger)
	case 7:
		if r.RequestedByID == nil {
			return nil
		}
		return string(*r.RequestedByID)
	case 8:
		if r.Content == "" {
			return nil
		}
		return r.Content
	case 9:
		if r.Facts == nil {
			return keel.EmptyJSONArray
		}
		return r.Facts
	case 10:
		if r.GuidanceIDs == nil {
			return keel.EmptyJSONArray
		}
		return r.GuidanceIDs
	case 11:
		return r.Digest
	case 12:
		if r.Model == "" {
			return nil
		}
		return r.Model
	case 13:
		if r.ProviderID == "" {
			return nil
		}
		return string(r.ProviderID)
	case 14:
		return int64(r.InputTokens)
	case 15:
		return int64(r.OutputTokens)
	case 16:
		if r.ErrorMessage == "" {
			return nil
		}
		return r.ErrorMessage
	case 17:
		return r.CheckedAt
	case 18:
		return r.Version
	case 19:
		return r.CreatedAt
	case 20:
		return r.UpdatedAt
	}
	return nil
}

func beforeCreateProfile(ctx context.Context, p unsafe.Pointer) error {
	return (*agentprofile.Profile)(p).BeforeCreate(ctx)
}

